INSERT INTO `achievement_reward_locale` VALUES (13,'esES','Nivel 80','Felicitaciones por tu convicción de llegar a la temporada 80 de aventuras. Sin duda, estás dedicado a la causa de librar a Azeroth de los males que nos han asolado.$B$BY aunque el viaje hasta ahora no ha sido una hazaña menor, la verdadera batalla está por llegar.$B$B¡Sigue luchando!$B$BRhonin'),(13,'esMX','Nivel 80','Felicitaciones por tu convicción de llegar a la temporada 80 de aventuras. Sin duda, estás dedicado a la causa de librar a Azeroth de los males que nos han asolado.$B$BY aunque el viaje hasta ahora no ha sido una hazaña menor, la verdadera batalla está por llegar.$B$B¡Sigue luchando!$B$BRhonin'),(45,'esES','¡Has estado por aquí!','Bueno, ¡mírate!$B$B¡Y pensé que había visto algunas cosas en este lugar helado! A este enano le parece obvio que tienes el fuego del explorador ardiendo en tus ojos.$B$BLleva este tabardo con orgullo. De esa manera, tus amigos sabrán a quién pedir direcciones cuando llegue el momento.$B$B¡Sigue en movimiento!$B$BBrann Barbabronce'),(45,'esMX','¡Has estado por aquí!','Bueno, ¡mírate!$B$B¡Y pensé que había visto algunas cosas en este lugar helado! A este enano le parece obvio que tienes el fuego del explorador ardiendo en tus ojos.$B$BLleva este tabardo con orgullo. De esa manera, tus amigos sabrán a quién pedir direcciones cuando llegue el momento.$B$B¡Sigue en movimiento!$B$BBrann Barbabronce'),(614,'esES','Â¡Por la Alianza!','La guerra hace estragos en nuestras tierras. Solo los héroes más valientes se atreven a desafiar a la Horda donde más les duele. Estás entre esos héroes.$B$BLos golpes que le has dado a los líderes de la Horda abrirán la puerta a nuestro asalto final. La Horda se inclinará ante el poder de la Alianza.$B$BTus acciones no quedarán sin recompensa. ¡Sigue adelante con orgullo!$B$B--Tu rey'),(614,'esMX','Â¡Por la Alianza!','La guerra hace estragos en nuestras tierras. Solo los héroes más valientes se atreven a desafiar a la Horda donde más les duele. Estás entre esos héroes.$B$BLos golpes que le has dado a los líderes de la Horda abrirán la puerta a nuestro asalto final. La Horda se inclinará ante el poder de la Alianza.$B$BTus acciones no quedarán sin recompensa. ¡Sigue adelante con orgullo!$B$B--Tu rey'),(619,'esES','Â¡Por la Horda!','En esta época de gran agitación, los verdaderos héroes surgen de la miseria. Eres uno de esos grandes héroes.$B$BLa guerra está sobre nosotros. Tus esfuerzos promoverán nuestra causa en Azeroth. Tus grandes hazañas serán recompensadas. Toma este premio de Orgrimmar y cabalga hacia la gloria.$B$B¡Por la Horda!$B$BJefe de Guerra Thrall'),(619,'esMX','Â¡Por la Horda!','En esta época de gran agitación, los verdaderos héroes surgen de la miseria. Eres uno de esos grandes héroes.$B$BLa guerra está sobre nosotros. Tus esfuerzos promoverán nuestra causa en Azeroth. Tus grandes hazañas serán recompensadas. Toma este premio de Orgrimmar y cabalga hacia la gloria.$B$B¡Por la Horda!$B$BJefe de Guerra Thrall'),(876,'esES','Te he estado mirando $gniño:niña;','Tienes una gran habilidad para vencer en esa arena. Guarda esto. Úsalo con orgullo. ¡Ahora vuelve y enséñales cómo se hace!$B$BTío sal'),(876,'esMX','Te he estado mirando $gniño:niña;','Tienes una gran habilidad para vencer en esa arena. Guarda esto. Úsalo con orgullo. ¡Ahora vuelve y enséñales cómo se hace!$B$BTío sal'),(1021,'esES','$gCompleto:Completa; $gTriunfador:Triunfadora;','No pude evitar darme cuenta de la excelente colección de tabardos que has conseguido reunir a lo largo de las temporadas. También podrías agregar este a tu colección. Simplemente ha estado acumulando polvo en mi armario.'),(1021,'esMX','$gCompleto:Completa; $gTriunfador:Triunfadora;','No pude evitar darme cuenta de la excelente colección de tabardos que has conseguido reunir a lo largo de las temporadas. También podrías agregar este a tu colección. Simplemente ha estado acumulando polvo en mi armario.'),(1250,'esES','El nuevo hogar de Stinker','Escuché lo bien que cuidas a nuestros amigos peludos. Espero que no te importe, pero debo conseguirle a Stinker un nuevo hogar. Simplemente se niega a jugar bien con los demás.$B$BAsegúrate de alimentarlo dos veces al día. Y umm... tiene algo con los gatos negros.$B$B--Breanni'),(1250,'esMX','El nuevo hogar de Stinker','Escuché lo bien que cuidas a nuestros amigos peludos. Espero que no te importe, pero debo conseguirle a Stinker un nuevo hogar. Simplemente se niega a jugar bien con los demás.$B$BAsegúrate de alimentarlo dos veces al día. Y umm... tiene algo con los gatos negros.$B$B--Breanni'),(2136,'esES','La gloria $gdel:de la; $ghéroe:heroína;','$gCampeón:Campeona;,$B$BHa llegado al Templo del Reposo del Dragón las grandes hazañas heroicas que has realizado desde que llegaste a Rasganorte.$B$BTu valentía no debe pasar desapercibida. Acepta este regalo en nombre de los Aspectos. Juntos libraremos a Azeroth del mal, de una vez y para siempre.$B$BAlexstrasza la Protectora'),(2136,'esMX','La gloria $gdel:de la; $ghéroe:heroína;','$gCampeón:Campeona;,$B$BHa llegado al Templo del Reposo del Dragón las grandes hazañas heroicas que has realizado desde que llegaste a Rasganorte.$B$BTu valentía no debe pasar desapercibida. Acepta este regalo en nombre de los Aspectos. Juntos libraremos a Azeroth del mal, de una vez y para siempre.$B$BAlexstrasza la Protectora'),(2143,'esES','Liderar la caballería','No pude evitar notar lo $gbueno:buena; que eres con el ganado. Con toda la actividad por aquí, el negocio ha ido mejor que nunca para mí. Supongo que no te importaría cuidar de este Draco Albino por mí. Simplemente no tengo suficientes minutos libres en el día para cuidar a todos estos animales.$B$BTuya, Mei'),(2143,'esMX','Liderar la caballería','No pude evitar notar lo $gbueno:buena; que eres con el ganado. Con toda la actividad por aquí, el negocio ha ido mejor que nunca para mí. Supongo que no te importaría cuidar de este Draco Albino por mí. Simplemente no tengo suficientes minutos libres en el día para cuidar a todos estos animales.$B$BTuya, Mei'),(2144,'esES','Una y otra vez','Con los tambores de guerra retumbando a lo lejos, es fácil para los habitantes de Azeroth olvidar todo lo que la vida tiene para ofrecer.$B$BTú, por otro lado, has mantenido la dignidad de las buenas razas de Azeroth con tu habilidad para recordar por qué luchamos. No celebrar nuestras victorias es otra forma de derrota. Recuérdalo bien, Juerguista.$B$BQue otros se inspiren en tus ganas de vivir.$B$BAlexstrasza la Protectora'),(2144,'esMX','Una y otra vez','Con los tambores de guerra retumbando a lo lejos, es fácil para los habitantes de Azeroth olvidar todo lo que la vida tiene para ofrecer.$B$BTú, por otro lado, has mantenido la dignidad de las buenas razas de Azeroth con tu habilidad para recordar por qué luchamos. No celebrar nuestras victorias es otra forma de derrota. Recuérdalo bien, Juerguista.$B$BQue otros se inspiren en tus ganas de vivir.$B$BAlexstrasza la Protectora'),(2516,'esES','Una amiga muy \"salá\"','¡Hola!$B$BTengo entendido que has conseguido un dulce y acogedor hogar incluso para ese travieso de Cuesqui... Tenía la esperanza de que quisieras acoger a otro huérfano inesperado.$B$BEsta Cervatilla es algo tímida, pero no tendrás ningún problema para ganarte su amistad con lo que te envío: ¡Su piedra de sal favorita!$B$B--Breanni'),(2516,'esMX','Una amiga muy \"salá\"','¡Hola!$B$BTengo entendido que has conseguido un dulce y acogedor hogar incluso para ese travieso de Cuesqui... Tenía la esperanza de que quisieras acoger a otro huérfano inesperado.$B$BEsta Cervatilla es algo tímida, pero no tendrás ningún problema para ganarte su amistad con lo que te envío: ¡Su piedra de sal favorita!$B$B--Breanni'),(2536,'esES','Un montón de monturas','Escuché que tus establos son casi tan extensos como los míos ahora. ¡Impresionante! Quizás podamos ayudarnos tu y yo... Tengo demasiados dracohalcones y esperaba que pudieras darle un hogar a este. Naturalmente, ha sido entrenado como montura y no como mascota de caza, y lo encontrarás tan leal e incansable como cualquier otro corcel que críe.$B$BTuya de nuevo, Mei'),(2536,'esMX','Un montón de monturas','Escuché que tus establos son casi tan extensos como los míos ahora. ¡Impresionante! Quizás podamos ayudarnos tu y yo... Tengo demasiados dracohalcones y esperaba que pudieras darle un hogar a este. Naturalmente, ha sido entrenado como montura y no como mascota de caza, y lo encontrarás tan leal e incansable como cualquier otro corcel que críe.$B$BTuya de nuevo, Mei'),(2537,'esES','Un montón de monturas','Escuché que tus establos son casi tan extensos como los míos ahora. ¡Impresionante! Quizás podamos ayudarnos tu y yo... Tengo demasiados dracohalcones y esperaba que pudieras darle un hogar a este. Naturalmente, ha sido entrenado como montura y no como mascota de caza, y lo encontrarás tan leal e incansable como cualquier otro corcel que críe.$B$BTuya de nuevo, Mei'),(2537,'esMX','Un montón de monturas','Escuché que tus establos son casi tan extensos como los míos ahora. ¡Impresionante! Quizás podamos ayudarnos tu y yo... Tengo demasiados dracohalcones y esperaba que pudieras darle un hogar a este. Naturalmente, ha sido entrenado como montura y no como mascota de caza, y lo encontrarás tan leal e incansable como cualquier otro corcel que críe.$B$BTuya de nuevo, Mei'),(2957,'esES','La gloria del asaltante de Ulduar','$gEstimado:Estimada; $n,$B$BEspero que estés bien y que hayas tenido tiempo de recuperarte de nuestras travesuras en Ulduar.$B$BMis muchachos del equipo de prospección se toparon con esta pobre cría de dragón de montar medio muerta. Debe haber sido un experimento de Enano de Hierro de algún tipo.$B$B¡Lo hemos cuidado para que recupere la salud y descubrirás que ya no es tan pequeño! Ninguno de nosotros sabe mucho acerca de montar otra cosa que no sean carneros y mulas de carga, y como te debíamos uno por lo que hiciste allí... Pensamos que quizás lo aceptarías como un regalo.$B$BTuyo,$BBrann Barbabronce'),(2957,'esMX','La gloria del asaltante de Ulduar','$gEstimado:Estimada; $n,$B$BEspero que estés bien y que hayas tenido tiempo de recuperarte de nuestras travesuras en Ulduar.$B$BMis muchachos del equipo de prospección se toparon con esta pobre cría de dragón de montar medio muerta. Debe haber sido un experimento de Enano de Hierro de algún tipo.$B$B¡Lo hemos cuidado para que recupere la salud y descubrirás que ya no es tan pequeño! Ninguno de nosotros sabe mucho acerca de montar otra cosa que no sean carneros y mulas de carga, y como te debíamos uno por lo que hiciste allí... Pensamos que quizás lo aceptarías como un regalo.$B$BTuyo,$BBrann Barbabronce'),(2958,'esES','La gloria del asaltante de Ulduar','$gEstimado:Estimada; $n,$B$BEspero que estés bien y que hayas tenido tiempo de recuperarte de nuestras travesuras en Ulduar.$B$BMis muchachos del equipo de prospección se toparon con esta pobre cría de dragón de montar medio muerta. Debe haber sido un experimento de Enano de Hierro de algún tipo.$B$B¡Lo hemos cuidado para que recupere la salud y descubrirás que ya no es tan pequeño! Ninguno de nosotros sabe mucho acerca de montar otra cosa que no sean carneros y mulas de carga, y como te debíamos uno por lo que hiciste allí... Pensamos que quizás lo aceptarías como un regalo.$B$BTuyo,$BBrann Barbabronce'),(2958,'esMX','La gloria del asaltante de Ulduar','$gEstimado:Estimada; $n,$B$BEspero que estés bien y que hayas tenido tiempo de recuperarte de nuestras travesuras en Ulduar.$B$BMis muchachos del equipo de prospección se toparon con esta pobre cría de dragón de montar medio muerta. Debe haber sido un experimento de Enano de Hierro de algún tipo.$B$B¡Lo hemos cuidado para que recupere la salud y descubrirás que ya no es tan pequeño! Ninguno de nosotros sabe mucho acerca de montar otra cosa que no sean carneros y mulas de carga, y como te debíamos uno por lo que hiciste allí... Pensamos que quizás lo aceptarías como un regalo.$B$BTuyo,$BBrann Barbabronce'),(3478,'esES','Un pavo aún no engullido','¿Puedes creer que este pavo regordete sobrevivió a noviembre?$B$BDado que todos sus amigos se han servido en abundantes mesas con salsa de arándanos y rellenos de pan con especias y... ooo... tengo hambre. ¡Pero de todos modos! Ahora está solo, así que esperaba que estuvieras dispuesto a cuidar de él. ¡Simplemente no queda suficiente espacio en mi tienda!$B$BMantenlo alejado de los fogones de cocina, por favor. Tiene esta extraña mirada en sus ojos alrededor de los fogones...'),(3478,'esMX','Un pavo aún no engullido','¿Puedes creer que este pavo regordete sobrevivió a noviembre?$B$BDado que todos sus amigos se han servido en abundantes mesas con salsa de arándanos y rellenos de pan con especias y... ooo... tengo hambre. ¡Pero de todos modos! Ahora está solo, así que esperaba que estuvieras dispuesto a cuidar de él. ¡Simplemente no queda suficiente espacio en mi tienda!$B$BMantenlo alejado de los fogones de cocina, por favor. Tiene esta extraña mirada en sus ojos alrededor de los fogones...'),(3857,'esES','$gMaestro:Maestra; de la Isla de la Conquista','Honorable $N,$B$BPor tus hazañas en la Isla de la Conquista, es un honor para mí presentarte este tabardo. Úselo con orgullo.$B$BAlto Comandante, Séptima Legión'),(3857,'esMX','$gMaestro:Maestra; de la Isla de la Conquista','Honorable $N,$B$BPor tus hazañas en la Isla de la Conquista, es un honor para mí presentarte este tabardo. Úselo con orgullo.$B$BAlto Comandante, Séptima Legión'),(3957,'esES','$gMaestro:Maestra; de la Isla de la Conquista','Honorable $N,$B$BPor tus hazañas en la Isla de la Conquista, es un honor para mí presentarte este tabardo. Úselo con orgullo.$B$BAlto Comandante, Séptima Legión'),(3957,'esMX','$gMaestro:Maestra; de la Isla de la Conquista','Honorable $N,$B$BPor tus hazañas en la Isla de la Conquista, es un honor para mí presentarte este tabardo. Úselo con orgullo.$B$BAlto Comandante, Séptima Legión'),(4079,'esES','Un tributo a la inmortalidad','Estimado $n,$B$BLos relatos de su actuación reciente en la Prueba del Gran Cruzado se contarán y volverán a contar durante siglos. Mientras la Cruzada Argenta hizo un llamado a los más grandes campeones de Azeroth para que pusieran a prueba su temple en el crisol del Coliseo, esperaba contra toda esperanza que los faros de luz como tú y tus compañeros pudieran emerger de la refriega.$B$BTe necesitaremos desesperadamente en la próxima batalla contra el Rey Exánime. Pero en este día, regocíjate y celebra tu glorioso logro y acepta este regalo; uno de nuestros mejores caballos de guerra. ¡Cuando la Plaga vea su estandarte asomándose en el horizonte, $ghéroe:heroína;, su fin estará cerca!$B$BTuyo con honor,$BTirion Vadin'),(4079,'esMX','Un tributo a la inmortalidad','Estimado $n,$B$BLos relatos de su actuación reciente en la Prueba del Gran Cruzado se contarán y volverán a contar durante siglos. Mientras la Cruzada Argenta hizo un llamado a los más grandes campeones de Azeroth para que pusieran a prueba su temple en el crisol del Coliseo, esperaba contra toda esperanza que los faros de luz como tú y tus compañeros pudieran emerger de la refriega.$B$BTe necesitaremos desesperadamente en la próxima batalla contra el Rey Exánime. Pero en este día, regocíjate y celebra tu glorioso logro y acepta este regalo; uno de nuestros mejores caballos de guerra. ¡Cuando la Plaga vea su estandarte asomándose en el horizonte, $ghéroe:heroína;, su fin estará cerca!$B$BTuyo con honor,$BTirion Vadin'),(4156,'esES','Un tributo a la inmortalidad','Estimado $n,$B$BLos relatos de su actuación reciente en la Prueba del Gran Cruzado se contarán y volverán a contar durante siglos. Mientras la Cruzada Argenta hizo un llamado a los más grandes campeones de Azeroth para que pusieran a prueba su temple en el crisol del Coliseo, esperaba contra toda esperanza que los faros de luz como tú y tus compañeros pudieran emerger de la refriega.$B$BTe necesitaremos desesperadamente en la próxima batalla contra el Rey Exánime. Pero en este día, regocíjate y celebra tu glorioso logro y acepta este regalo; uno de nuestros mejores caballos de guerra. ¡Cuando la Plaga vea su estandarte asomándose en el horizonte, $ghéroe:heroína;, su fin estará cerca!$B$BTuyo con honor,$BTirion Vadin'),(4156,'esMX','Un tributo a la inmortalidad','Estimado $n,$B$BLos relatos de su actuación reciente en la Prueba del Gran Cruzado se contarán y volverán a contar durante siglos. Mientras la Cruzada Argenta hizo un llamado a los más grandes campeones de Azeroth para que pusieran a prueba su temple en el crisol del Coliseo, esperaba contra toda esperanza que los faros de luz como tú y tus compañeros pudieran emerger de la refriega.$B$BTe necesitaremos desesperadamente en la próxima batalla contra el Rey Exánime. Pero en este día, regocíjate y celebra tu glorioso logro y acepta este regalo; uno de nuestros mejores caballos de guerra. ¡Cuando la Plaga vea su estandarte asomándose en el horizonte, $ghéroe:heroína;, su fin estará cerca!$B$BTuyo con honor,$BTirion Vadin'),(4478,'esES','P.U.G.','Estimado individuo muy paciente,$B$BNos gustaría reconocer su tenacidad en la gestión de mazmorras con personas que probablemente no haya conocido antes. Con suerte, incluso les enseñaste a algunos novatos las cuerdas en tus grupos de recogida.$B$BEn resumen, escuchamos que te gustan los pugs. Así que aquí tienes un pug para tu pug, para que puedas pug mientras pug. O algo.$B$BAbrazos,$B$BTus amigos del equipo de desarrollo de WoW.'),(4478,'esMX','P.U.G.','Estimado individuo muy paciente,$B$BNos gustaría reconocer su tenacidad en la gestión de mazmorras con personas que probablemente no haya conocido antes. Con suerte, incluso les enseñaste a algunos novatos las cuerdas en tus grupos de recogida.$B$BEn resumen, escuchamos que te gustan los pugs. Así que aquí tienes un pug para tu pug, para que puedas pug mientras pug. O algo.$B$BAbrazos,$B$BTus amigos del equipo de desarrollo de WoW.'),(4602,'esES','La gloria del asaltante de Corona de Hielo','$n,$B$BA medida que la influencia del Rey Exánime se desvanece, algunos de sus secuaces más poderosos se han liberado de sus manos.$B$BEste dragón vermis de hielo que mis hombres capturaron es un excelente ejemplo. Ella tiene voluntad propia y algo más.$B$BUno de mis hombres perdió un brazo al domarla, pero ahora se adapta bastante bien a los jinetes, siempre que ellos mismos sean hábiles y de voluntad fuerte.$B$BAcepta esta magnífica bestia como regalo de los Caballeros de la Espada de Ébano. Fue un honor luchar a tu lado en esta gran batalla.$B$BCon honor,$BDarion Mograine.'),(4602,'esMX','La gloria del asaltante de Corona de Hielo','$n,$B$BA medida que la influencia del Rey Exánime se desvanece, algunos de sus secuaces más poderosos se han liberado de sus manos.$B$BEste dragón vermis de hielo que mis hombres capturaron es un excelente ejemplo. Ella tiene voluntad propia y algo más.$B$BUno de mis hombres perdió un brazo al domarla, pero ahora se adapta bastante bien a los jinetes, siempre que ellos mismos sean hábiles y de voluntad fuerte.$B$BAcepta esta magnífica bestia como regalo de los Caballeros de la Espada de Ébano. Fue un honor luchar a tu lado en esta gran batalla.$B$BCon honor,$BDarion Mograine.'),(4603,'esES','La gloria del asaltante de Corona de Hielo','$n,$B$BA medida que la influencia del Rey Exánime se desvanece, algunos de sus secuaces más poderosos se han liberado de sus manos.$B$BEste dragón vermis de hielo que mis hombres capturaron es un excelente ejemplo. Ella tiene voluntad propia y algo más.$B$BUno de mis hombres perdió un brazo al domarla, pero ahora se adapta bastante bien a los jinetes, siempre que ellos mismos sean hábiles y de voluntad fuerte.$B$BAcepta esta magnífica bestia como regalo de los Caballeros de la Espada de Ébano. Fue un honor luchar a tu lado en esta gran batalla.$B$BCon honor,$BDarion Mograine.'),(4603,'esMX','La gloria del asaltante de Corona de Hielo','$n,$B$BA